%%\ Lab 4: Noise and Filtering
% Course: Mathematical Algorithms (DSP) — Image Processing Labs
close all; clear; clc;

if ~exist('screenshots', 'dir')
    mkdir('screenshots');
end

if exist('peppers.png', 'file')
    I = im2double(rgb2gray(imread('peppers.png')));
else
    I = im2double(imread('cameraman.tif'));
end

% Helper function for Signal-to-Noise Ratio (SNR in dB)
calc_snr = @(est, ref) 10 * log10(sum(ref(:).^2) / sum((est(:) - ref(:)).^2));

%%\ 1) Add different noise types
I_gauss = imnoise(I, 'gaussian', 0, 0.01);
I_sp    = imnoise(I, 'salt & pepper', 0.05);

f1 = figure; %[output:5dd6a360]
montage({I, I_gauss, I_sp}, 'Size', [1 3]); %[output:5dd6a360]
title('Original | Gaussian noise | Salt & pepper noise'); %[output:5dd6a360]
saveas(f1, fullfile('screenshots', '01_noise_types.png')); %[output:5dd6a360]

%%\ 2) Compute simple quality metrics
MSE_gauss = immse(I_gauss, I);
MSE_sp    = immse(I_sp, I);
SNR_gauss = calc_snr(I_gauss, I);
SNR_sp    = calc_snr(I_sp, I);

fprintf('Gaussian Noise -> MSE: %.4f | SNR: %.2f dB\n', MSE_gauss, SNR_gauss); %[output:5f5c8c44]
fprintf('S&P Noise      -> MSE: %.4f | SNR: %.2f dB\n', MSE_sp, SNR_sp); %[output:983037ec]

%%\ 3) Linear filtering (mean, Gaussian)
h_avg         = fspecial('average', 3);
I_avg_gauss   = imfilter(I_gauss, h_avg, 'replicate');
I_avg_sp      = imfilter(I_sp, h_avg, 'replicate');

h_gauss       = fspecial('gaussian', [3 3], 0.7);
I_gauss_gauss = imfilter(I_gauss, h_gauss, 'replicate');
I_gauss_sp    = imfilter(I_sp, h_gauss, 'replicate');

f3 = figure; %[output:5c1abad9]
montage({I_gauss, I_avg_gauss, I_gauss_gauss}, 'Size', [1 3]); %[output:5c1abad9]
title('Gaussian Noise | 3x3 Mean Filter | 3x3 Gaussian Filter (\sigma=0.7)'); %[output:5c1abad9]
saveas(f3, fullfile('screenshots', '03_linear_filtering.png')); %[output:5c1abad9]

%%\ 4) Non-linear filtering (median)
I_med_gauss = medfilt2(I_gauss, [3 3]);
I_med_sp    = medfilt2(I_sp, [3 3]);

f4 = figure; %[output:5ee61a22]
montage({I_avg_sp, I_med_sp, I_avg_gauss, I_med_gauss}, 'Size', [2 2]); %[output:5ee61a22]
title('Top: Avg vs Median (S&P) | Bottom: Avg vs Median (Gaussian)'); %[output:5ee61a22]
saveas(f4, fullfile('screenshots', '04_avg_vs_median.png')); %[output:5ee61a22]

%%\ 5) Compare metrics after filtering
fprintf('After filtering, MSE S&P avg=%.4f, med=%.4f\n', ... %[output:group:515e3f22] %[output:2f49593b]
    immse(I_avg_sp, I), immse(I_med_sp, I)); %[output:group:515e3f22] %[output:2f49593b]

Condition = { ...
    'Gaussian Noise (Unfiltered)'; ...
    'Gaussian + 3x3 Mean'; ...
    'Gaussian + 3x3 Gaussian (sigma=0.7)'; ...
    'Gaussian + 3x3 Median'; ...
    'Salt & Pepper (Unfiltered)'; ...
    'Salt & Pepper + 3x3 Mean'; ...
    'Salt & Pepper + 3x3 Gaussian (sigma=0.7)'; ...
    'Salt & Pepper + 3x3 Median'};

MSE_val = [ ...
    MSE_gauss; immse(I_avg_gauss, I); immse(I_gauss_gauss, I); immse(I_med_gauss, I); ...
    MSE_sp;    immse(I_avg_sp, I);    immse(I_gauss_sp, I);    immse(I_med_sp, I)];

SNR_dB = [ ...
    SNR_gauss; calc_snr(I_avg_gauss, I); calc_snr(I_gauss_gauss, I); calc_snr(I_med_gauss, I); ...
    SNR_sp;    calc_snr(I_avg_sp, I);    calc_snr(I_gauss_sp, I);    calc_snr(I_med_sp, I)];

results_table = table(Condition, round(MSE_val, 5), round(SNR_dB, 2), ...
    'VariableNames', {'Condition', 'MSE', 'SNR_dB'});
disp(results_table); %[output:81267618]

% Print Markdown rows for direct copy-paste into README.md
fprintf('\n--- Copy into README.md ---\n'); %[output:5996645e]
for k = 1:height(results_table) %[output:group:4b5f4368]
    fprintf('| %s | %.5f | %.2f dB |\n', ... %[output:884decba]
        results_table.Condition{k}, results_table.MSE(k), results_table.SNR_dB(k)); %[output:884decba]
end %[output:group:4b5f4368]

